namespace mal{namespace dgf{class QuotientGrid{int n_,root_;std::vector<int>xs_;public:explicit QuotientGrid(int n):n_(n),root_(0){if(n<1)throw std::invalid_argument("block sieve: N must be positive");while(1LL*(root_+1)*(root_+1)<=n)++root_;for(int i=1;i<=root_;++i)xs_.push_back(i);for(int i=n/(root_+1);i>=1;--i)xs_.push_back(n/i);}int limit()const{return n_;}int root()const{return root_;}const std::vector<int>&values()const{return xs_;}int index(int x)const{if(x<1||x>n_)throw std::out_of_range("block sieve: invalid value");if(x<=root_)return x-1;int i=n_/x;int id=int(xs_.size())-i;if(xs_[id]!=x)throw std::invalid_argument("block sieve: x not in D(N)");return id;}bool contains(int x)const{return x>=1&&x<=n_&&(x<=root_||n_/(n_/x)==x);}};class BlockPrefix{const QuotientGrid*grid_;std::vector<coef>sums_;public:explicit BlockPrefix(const QuotientGrid&g):grid_(&g),sums_(g.values().size()){}BlockPrefix(const QuotientGrid&g,const series&points):BlockPrefix(g){if(int(points.size())<=g.limit()||points[0]!=coef(0))throw std::invalid_argument("block sieve: points must cover N");coef sum=0;std::size_t i=0;for(int x=1;x<=g.limit();++x){sum+=points[x];if(i<sums_.size()&&g.values()[i]==x)sums_[i++]=sum;}}const QuotientGrid&grid()const{return*grid_;}coef at(int x)const{return x==0?coef(0):sums_[grid_->index(x)];}coef&operator[](std::size_t i){return sums_[i];}coef operator[](std::size_t i)const{return sums_[i];}std::size_t size()const{return sums_.size();}coef point(int x)const{return at(x)-at(x-1);}};inline void same_grid(const BlockPrefix&a,const BlockPrefix&b){if(&a.grid()!=&b.grid())throw std::invalid_argument("block sieve: different grids");}inline int block_threshold(const QuotientGrid&g,const series&dense){int t=int(dense.size())-1;if(dense.empty()||dense[0]!=coef(0)||t<g.root()||t>g.limit())throw std::invalid_argument("block sieve: dense prefix must cover sqrt(N)");return t;}inline BlockPrefix block_convolve(const BlockPrefix&f,const BlockPrefix&g,const series&dense_h){same_grid(f,g);const QuotientGrid&grid=f.grid();int t=block_threshold(grid,dense_h);BlockPrefix h(grid);coef prefix=0;for(std::size_t i=0;i<h.size();++i){int x=grid.values()[i];if(x<=t){int previous=i?grid.values()[i-1]:0;for(int j=previous+1;j<=x;++j)prefix+=dense_h[j];h[i]=prefix;continue;}int r=int(std::sqrt(double(x)));while(1LL*(r+1)*(r+1)<=x)++r;while(1LL*r*r>x)--r;coef sum=coef(0)-f.at(r)*g.at(r);for(int j=1;j<=r;++j)sum+=f.point(j)*g.at(x/j)+g.point(j)*f.at(x/j);h[i]=sum;}return h;}inline BlockPrefix block_convolve(const BlockPrefix&f,const BlockPrefix&g,const series&dense_f,const series&dense_g){same_grid(f,g);int t=block_threshold(f.grid(),dense_f);if(int(dense_g.size())!=t+1||dense_g[0]!=coef(0))throw std::invalid_argument("block sieve: different dense limits");return block_convolve(f,g,mul(dense_f,dense_g));}inline BlockPrefix block_convolve_one_multiplicative(const BlockPrefix&f,const BlockPrefix&g,const series&dense_f,const series&dense_g){same_grid(f,g);int t=block_threshold(f.grid(),dense_f);if(int(dense_g.size())!=t+1||dense_g[0]!=coef(0)||dense_g[1]!=coef(1))throw std::invalid_argument("block sieve: incompatible dense multiplicative operand");return block_convolve(f,g,mul_multiplicative(dense_f,dense_g));}inline BlockPrefix block_convolve_ranked(const BlockPrefix&f,const BlockPrefix&g,const series&dense_f,const series&dense_g){same_grid(f,g);int t=block_threshold(f.grid(),dense_f);if(int(dense_g.size())!=t+1||dense_g[0]!=coef(0))throw std::invalid_argument("block sieve: different dense limits");return block_convolve(f,g,fast_mul(dense_f,dense_g));}inline BlockPrefix dujiao_direct(const BlockPrefix&b,const BlockPrefix&c,const series&dense_a){same_grid(b,c);const QuotientGrid&grid=b.grid();int t=block_threshold(grid,dense_a);coef b1=b.at(1);if(b1==coef(0))throw std::invalid_argument("block sieve: B(1) must be nonzero");coef inv1=b1.inv(),prefix=0;BlockPrefix a(grid);for(std::size_t i=0;i<a.size();++i){int x=grid.values()[i];if(x<=t){int previous=i?grid.values()[i-1]:0;for(int j=previous+1;j<=x;++j)prefix+=dense_a[j];a[i]=prefix;continue;}coef sum=c.at(x);for(int l=2,r;l<=x;l=r+1){int q=x/l;r=x/q;sum-=(b.at(r)-b.at(l-1))*a.at(q);}a[i]=sum*inv1;}return a;}inline BlockPrefix dujiao_zak(const BlockPrefix&b,const BlockPrefix&c,const series&dense_b,const series&dense_c){same_grid(b,c);const QuotientGrid&grid=b.grid();int t=block_threshold(grid,dense_b);if(int(dense_c.size())!=t+1||dense_c[0]!=coef(0))throw std::invalid_argument("block sieve: different dense limits");if(dense_b[1]==coef(0))throw std::invalid_argument("block sieve: B(1) must be nonzero");series a0=div(dense_c,dense_b);BlockPrefix small(grid);coef sum=0;for(std::size_t i=0;i<small.size();++i){int x=grid.values()[i];if(x<=t){int previous=i?grid.values()[i-1]:0;for(int j=previous+1;j<=x;++j)sum+=a0[j];}small[i]=sum;}BlockPrefix product=block_convolve(b,small,dense_c);BlockPrefix tail(grid),answer(grid);coef inv1=dense_b[1].inv();for(std::size_t i=0;i<answer.size();++i){int x=grid.values()[i];if(x>t){coef v=c[i]-product[i];for(int k=2;k<=x/(t+1);++k)v-=dense_b[k]*tail.at(x/k);tail[i]=v*inv1;}answer[i]=small[i]+tail[i];}return answer;}}}
